entries[173978] = { ["name"] = "Festmahl des Blutes", ["text"] = "Wirken in 3 sek.\nReagenzien:\nRohes Elekkfleisch (10), Rohes Eberfleisch (10), Rohes Talbukfleisch (10), Rohes Flussbestienfleisch (10), Rylakei (10), Rohes Grollhuffleisch (10)\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBeruf:\nKochkunst von Draenor (1)\nEntdeckung:\nKochrezepte von Draenor\n\nBenutzen: Sättigt bis zu 30 Mitglieder Eures Schlachtzugs oder Eurer Gruppe mit einem Festmahl des Blutes.\n\nDabei besteht eine Chance, dass Ihr das Rezept erlernt.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und der Wert, auf den Ihr abgestimmt seid, wird 1 Stunde lang um 550 erhöht.\n35" }
entries[173979] = { ["name"] = "Festmahl der Gewässer", ["text"] = "Wirken in 3 sek.\nReagenzien:\nSeeskorpionsegment (10), Fleisch eines Tiefenschluckaals (10), Fleisch eines blinden Seestörs (10), Fleisch eines dicken Schläfers (10), Feuerammonittentakel (10), Fleisch eines kieferlosen Schleichers (10)\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBeruf:\nKochkunst von Draenor (1)\nEntdeckung:\nKochrezepte von Draenor\n\nBenutzen: Sättigt bis zu 10 Mitglieder Eures Schlachtzugs oder Eurer Gruppe mit einem Festmahl der Gewässer.\n\nDabei besteht eine Chance, dass Ihr das Rezept erlernt.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und der Wert, auf den Ihr abgestimmt seid, wird 1 Stunde lang um 550 erhöht.\n35" }
