entries[174502] = { ["name"] = "T.R.I.T.-Technik", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nT.R.I.T.-Technik: Telematische Reflex-Initiierungs- und Transmissions-Technologie. Man könnte auch einfach \"Tritt\" dazu sagen, aber das war \"gewissen Herrschaften\" wohl nicht \"technisch\" genug. Verursacht körperlichen Schaden und betäubt den Gegner für 4 Sek." }
